}

void ConfirmDialog::callbackActive(Widget &widget) {
	if (widget.getTag() == "BTN_OK") {
		_accepted = true;
		_returnCode = kReturnCodeAbort;
		return;
	}
	if (widget.getTag() == "BTN_CANCEL") {
		_accepted = false;
		_returnCode = kReturnCodeAbort;
		return;
	}
}

