		lblInvHead->hide();
		lblInvHands->hide();
		lblInvArmL->hide();
		lblInvBody->hide();
		lblInvArmR->hide();
		lblInvWeapL->hide();
		lblInvBelt->hide();
		lblInvWeapR->hide();

		lblTxtBar->hide();
		lblSlotName->hide();
		lblPortBord->hide();
		lblPortrait->hide();

		lbItems->setItemSelectionEnabled(true);
		lbItems->setItemBorderColor(0.0f, 0.648438f, 0.968750f, 1.0f);
		lbItems->selectItemByWidgetTag("LB_ITEMS_ITEM_0");

		btnBack->setText(TalkMan.getString(1581));
	} else {
		lbDesc->hide();

		btnInvImplant->show();
		btnInvHead->show();
