/** @file
 *  The ingame minimap.
 */

#include "external/glm/mat4x4.hpp"
#include "external/glm/gtc/type_ptr.hpp"
#include "external/glm/gtc/matrix_transform.hpp"

#include "src/common/util.h"

#include "src/engines/kotor/gui/ingame/minimap.h"

namespace Engines {

